// Database schema — «دخل‌وخرج» (docs/schema.md).
// Better Auth core tables follow the schema generated by the official
// Better Auth CLI (username plugin) for the installed version; domain
// tables implement docs/schema.md. Money columns are integers in minor
// units (IRR stored in Rial); timestamps are UTC; financial day/month
// keys are Jalali strings in Asia/Tehran.
import { relations, sql } from "drizzle-orm";
import {
  sqliteTable,
  text,
  integer,
  index,
  uniqueIndex,
} from "drizzle-orm/sqlite-core";

/* ─────────── Better Auth core (CLI-generated) ─────────── */

export const user = sqliteTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: integer("email_verified", { mode: "boolean" })
    .default(false)
    .notNull(),
  image: text("image"),
  createdAt: integer("created_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull(),
  updatedAt: integer("updated_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .$onUpdate(() => new Date())
    .notNull(),
  username: text("username").unique(),
  displayUsername: text("display_username"),
});

export const session = sqliteTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
    token: text("token").notNull().unique(),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("session_userId_idx").on(table.userId)],
);

export const account = sqliteTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: integer("access_token_expires_at", {
      mode: "timestamp_ms",
    }),
    refreshTokenExpiresAt: integer("refresh_token_expires_at", {
      mode: "timestamp_ms",
    }),
    scope: text("scope"),
    password: text("password"),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("account_userId_idx").on(table.userId)],
);

export const verification = sqliteTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("verification_identifier_idx").on(table.identifier)],
);

export const userRelations = relations(user, ({ many }) => ({
  sessions: many(session),
  accounts: many(account),
}));

export const sessionRelations = relations(session, ({ one }) => ({
  user: one(user, { fields: [session.userId], references: [user.id] }),
}));

export const accountRelations = relations(account, ({ one }) => ({
  user: one(user, { fields: [account.userId], references: [user.id] }),
}));

/* ─────────── Domain tables (docs/schema.md) ─────────── */

// One-time recovery codes: only sha-256 hashes are stored.
export const recoveryCodes = sqliteTable(
  "recovery_code",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    codeHash: text("code_hash").notNull(),
    usedAt: integer("used_at", { mode: "timestamp_ms" }),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
  },
  (table) => [index("recovery_code_userId_idx").on(table.userId)],
);

// App-level preferences (kept out of the Better Auth user table on purpose).
export const settings = sqliteTable("settings", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  // toman (default) | rial — display unit only; storage is always IRR/Rial.
  displayUnit: text("display_unit").notNull().default("toman"),
  // light (default) | dark
  theme: text("theme").notNull().default("light"),
  createdAt: integer("created_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull(),
  updatedAt: integer("updated_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .$onUpdate(() => new Date())
    .notNull(),
});

// Financial accounts. `balanceMinor` is a cache maintained in the same
// batch as every transaction write and verified against the computed
// value (opening + signed sum) by tests.
export const accounts = sqliteTable(
  "account_entry",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    // bank | cash | wallet | savings | credit | custom
    type: text("type").notNull(),
    bankCode: text("bank_code"),
    cardLast4: text("card_last4"),
    openingBalanceMinor: integer("opening_balance_minor").notNull().default(0),
    currency: text("currency").notNull().default("IRR"),
    balanceMinor: integer("balance_minor").notNull().default(0),
    archivedAt: integer("archived_at", { mode: "timestamp_ms" }),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
    deletedAt: integer("deleted_at", { mode: "timestamp_ms" }),
  },
  (table) => [index("account_entry_userId_idx").on(table.userId)],
);

export const categories = sqliteTable(
  "category",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    // income | expense
    kind: text("kind").notNull(),
    name: text("name").notNull(),
    icon: text("icon"),
    color: text("color"),
    isSeed: integer("is_seed", { mode: "boolean" }).notNull().default(false),
    archivedAt: integer("archived_at", { mode: "timestamp_ms" }),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
    deletedAt: integer("deleted_at", { mode: "timestamp_ms" }),
  },
  (table) => [index("category_userId_idx").on(table.userId)],
);

export const people = sqliteTable(
  "person",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    phone: text("phone"),
    note: text("note"),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
    deletedAt: integer("deleted_at", { mode: "timestamp_ms" }),
  },
  (table) => [index("person_userId_idx").on(table.userId)],
);

export const transactions = sqliteTable(
  "transaction",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accountId: text("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    // INCOME | EXPENSE | TRANSFER | DEBT_BORROWED | DEBT_LENT |
    // REPAYMENT_PAID | REPAYMENT_RECEIVED
    type: text("type").notNull(),
    // Always a positive integer; the sign comes from the type via
    // signedAmount() in src/shared/domain — never store negatives here.
    amountMinor: integer("amount_minor").notNull(),
    currency: text("currency").notNull().default("IRR"),
    // Jalali YYYY-MM-DD in Asia/Tehran (financial day).
    dayKey: text("day_key").notNull(),
    // Jalali YYYY-MM (financial month).
    monthKey: text("month_key").notNull(),
    occurredAt: integer("occurred_at", { mode: "timestamp_ms" }).notNull(),
    categoryId: text("category_id").references(() => categories.id),
    personId: text("person_id").references(() => people.id),
    // card | cash | bank_transfer | card_to_card | other
    paymentMethod: text("payment_method"),
    note: text("note"),
    // Transfer legs share a transferId; from-leg and to-leg.
    transferId: text("transfer_id"),
    transferLeg: text("transfer_leg"),
    // Optional counterparty account of a transfer (the other leg).
    relatedAccountId: text("related_account_id"),
    // Debt movements reference the debt they belong to.
    debtId: text("debt_id"),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
    deletedAt: integer("deleted_at", { mode: "timestamp_ms" }),
  },
  (table) => [
    index("transaction_userId_idx").on(table.userId),
    index("transaction_accountId_idx").on(table.accountId),
    index("transaction_monthKey_idx").on(table.monthKey),
    index("transaction_transferId_idx").on(table.transferId),
    index("transaction_debtId_idx").on(table.debtId),
    index("transaction_categoryId_idx").on(table.categoryId),
  ],
);

export const debts = sqliteTable(
  "debt",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    personId: text("person_id")
      .notNull()
      .references(() => people.id, { onDelete: "cascade" }),
    // borrowed (بدهی من) | lent (طلب من)
    direction: text("direction").notNull(),
    principalMinor: integer("principal_minor").notNull(),
    currency: text("currency").notNull().default("IRR"),
    // Optional linked account: movements hit the account balance without
    // ever counting as income or expense.
    accountId: text("account_id").references(() => accounts.id),
    dueDayKey: text("due_day_key"),
    installments: integer("installments"),
    note: text("note"),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
    deletedAt: integer("deleted_at", { mode: "timestamp_ms" }),
  },
  (table) => [
    index("debt_userId_idx").on(table.userId),
    index("debt_personId_idx").on(table.personId),
  ],
);

export const budgets = sqliteTable(
  "budget",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    // Jalali YYYY-MM.
    monthKey: text("month_key").notNull(),
    limitMinor: integer("limit_minor").notNull(),
    currency: text("currency").notNull().default("IRR"),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
    deletedAt: integer("deleted_at", { mode: "timestamp_ms" }),
  },
  (table) => [index("budget_userId_idx").on(table.userId)],
);

export const budgetCategories = sqliteTable(
  "budget_category",
  {
    id: text("id").primaryKey(),
    budgetId: text("budget_id")
      .notNull()
      .references(() => budgets.id, { onDelete: "cascade" }),
    categoryId: text("category_id")
      .notNull()
      .references(() => categories.id, { onDelete: "cascade" }),
  },
  (table) => [
    uniqueIndex("budget_category_pair_idx").on(table.budgetId, table.categoryId),
  ],
);

// Generic D1-backed rate limiting (auth, import, export endpoints).
export const rateLimits = sqliteTable(
  "rate_limit",
  {
    id: text("id").primaryKey(),
    key: text("key").notNull(),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
  },
  (table) => [index("rate_limit_key_idx").on(table.key)],
);

/* ─────────── Inferred types ─────────── */

export type User = typeof user.$inferSelect;
export type SessionRow = typeof session.$inferSelect;
export type AccountEntry = typeof accounts.$inferSelect;
export type Category = typeof categories.$inferSelect;
export type Person = typeof people.$inferSelect;
export type Transaction = typeof transactions.$inferSelect;
export type Debt = typeof debts.$inferSelect;
export type Budget = typeof budgets.$inferSelect;
